package com.slayercapereminder;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Slayer Cape Reminder",
	description = "Reminds you to retrieve your Slayer Cape from the bank if it is not in your inventory or equipped.",
	tags = {"slayer", "cape", "reminder", "bank"}
)
public class SlayerCapeReminderPlugin extends Plugin
{
	static final String TASK_COMPLETE_MESSAGE = "return to a Slayer master";
	private static final int PROXIMITY_DISTANCE = 16;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SlayerCapeReminderOverlay overlay;

	@Inject
	private SlayerCapeReminderConfig config;

	// Package-private so the overlay can read them directly.
	boolean capePresent = true;
	boolean taskComplete = false;
	boolean isLevel99 = false;
	boolean nearSlayerMaster = false;
	boolean hasActiveTask = false;

	private long taskCompleteTime = 0;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		clientThread.invokeLater(() -> {
			updateCapePresence();
			updateSlayerLevel();
			hasActiveTask = client.getVarpValue(VarPlayerID.SLAYER_COUNT) > 0;
		});
		log.debug("SlayerCapeReminderPlugin started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		capePresent = true;
		taskComplete = false;
		isLevel99 = false;
		nearSlayerMaster = false;
		hasActiveTask = false;
		log.debug("SlayerCapeReminderPlugin stopped");
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		switch (event.getType())
		{
			case GAMEMESSAGE:
			case SPAM:
				break;
			default:
				return;
		}

		String message = Text.removeTags(event.getMessage());

		if (message.contains(TASK_COMPLETE_MESSAGE))
		{
			taskComplete = true;
			taskCompleteTime = System.currentTimeMillis();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		updateNearSlayerMaster();

		if (!taskComplete)
		{
			return;
		}

		int delay = config.dismissDelay();
		if (delay > 0 && System.currentTimeMillis() - taskCompleteTime >= delay * 1000L)
		{
			taskComplete = false;
		}
	}

	private void updateNearSlayerMaster()
	{
		if (client.getLocalPlayer() == null)
		{
			nearSlayerMaster = false;
			return;
		}

		WorldPoint player = client.getLocalPlayer().getWorldLocation();

		nearSlayerMaster =
			(config.proximityDuradel() && isNearMaster(player, SlayerMaster.DURADEL.getLocation())) ||
			(config.proximityNieve() && isNearMaster(player, SlayerMaster.NIEVE.getLocation())) ||
			(config.proximityKonar() && isNearMaster(player, SlayerMaster.KONAR.getLocation())) ||
			(config.proximityKrystilia() && isNearMaster(player, SlayerMaster.KRYSTILIA.getLocation()));
	}

	private boolean isNearMaster(WorldPoint player, WorldPoint master)
	{
		return player.distanceTo2D(master) <= PROXIMITY_DISTANCE;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() != VarPlayerID.SLAYER_COUNT)
		{
			return;
		}

		int newSize = event.getValue();
		hasActiveTask = newSize > 0;

		if (newSize > 0)
		{
			// New task assigned — hide the reminder.
			taskComplete = false;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			updateCapePresence();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGING_IN || state == GameState.LOGIN_SCREEN)
		{
			capePresent = true;
			taskComplete = false;
			nearSlayerMaster = false;
			hasActiveTask = false;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() == Skill.SLAYER)
		{
			updateSlayerLevel();
		}
	}

	private void updateSlayerLevel()
	{
		isLevel99 = client.getRealSkillLevel(Skill.SLAYER) >= 99;
	}

	private void updateCapePresence()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);

		boolean inInventory = inventory != null
			&& (inventory.contains(ItemID.SKILLCAPE_SLAYER) || inventory.contains(ItemID.SKILLCAPE_SLAYER_TRIMMED));
		boolean equipped = equipment != null
			&& (equipment.contains(ItemID.SKILLCAPE_SLAYER) || equipment.contains(ItemID.SKILLCAPE_SLAYER_TRIMMED));

		capePresent = inInventory || equipped;
	}

	@Provides
	SlayerCapeReminderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerCapeReminderConfig.class);
	}
}

package com.slayercapereminder;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

public class SlayerCapeReminderOverlay extends OverlayPanel
{
	private final SlayerCapeReminderPlugin plugin;
	private final SlayerCapeReminderConfig config;

	@Inject
	public SlayerCapeReminderOverlay(SlayerCapeReminderPlugin plugin, SlayerCapeReminderConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		boolean levelOk = !config.onlyAt99() || plugin.isLevel99;
		boolean proximityTrigger = plugin.nearSlayerMaster && !plugin.hasActiveTask;

		if (plugin.capePresent || !levelOk || (!plugin.taskComplete && !proximityTrigger))
		{
			return null;
		}

		boolean flash = config.flashEnabled() && (System.currentTimeMillis() / 600) % 2 == 0;
		panelComponent.setBackgroundColor(flash ? config.flashColor() : config.backgroundColor());
		panelComponent.getChildren().add(LineComponent.builder()
			.left(config.reminderText())
			.leftColor(config.warningColor())
			.build());

		return super.render(graphics);
	}
}

package com.slayercapereminder;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.coords.WorldPoint;

@Getter
@RequiredArgsConstructor
enum SlayerMaster
{
	DURADEL(new WorldPoint(2869, 2982, 1)),
	NIEVE(new WorldPoint(2432, 3423, 0)),
	KONAR(new WorldPoint(1309, 3785, 0)),
	KRYSTILIA(new WorldPoint(3109, 3516, 0));

	private final WorldPoint location;
}

package com.slayercapereminder;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("slayercapereminder")
public interface SlayerCapeReminderConfig extends Config
{
	@ConfigItem(
		keyName = "onlyAt99",
		name = "Only at 99 Slayer",
		description = "Only show the overlay if you have 99 Slayer.",
		position = 0
	)
	default boolean onlyAt99()
	{
		return true;
	}

	@ConfigItem(
		keyName = "reminderText",
		name = "Reminder text",
		description = "Text displayed in the overlay when your Slayer Cape is absent.",
		position = 1
	)
	default String reminderText()
	{
		return "Get your Slayer Cape!";
	}

	@ConfigItem(
		keyName = "warningColor",
		name = "Text color",
		description = "Color of the reminder text.",
		position = 2
	)
	default Color warningColor()
	{
		return Color.RED;
	}

	@ConfigItem(
		keyName = "backgroundColor",
		name = "Background color",
		description = "Color of the overlay box background.",
		position = 3
	)
	default Color backgroundColor()
	{
		return new Color(70, 61, 50, 156);
	}

	@ConfigItem(
		keyName = "flashEnabled",
		name = "Flash background",
		description = "Flashes the overlay background between the background color and the flash color.",
		position = 4
	)
	default boolean flashEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "flashColor",
		name = "Flash color",
		description = "Second background color used when flashing is enabled.",
		position = 5
	)
	default Color flashColor()
	{
		return new Color(150, 0, 0, 156);
	}

	@ConfigItem(
		keyName = "dismissDelay",
		name = "Auto-dismiss delay",
		description = "Seconds before the overlay automatically hides after a task is completed. Set to 0 to never auto-dismiss.",
		position = 6
	)
	@Range(min = 0)
	@Units(Units.SECONDS)
	default int dismissDelay()
	{
		return 120;
	}

	@ConfigSection(
		name = "Proximity Alert",
		description = "Show the overlay when approaching a slayer master without your cape and without an active task.",
		position = 7
	)
	String proximitySection = "proximitySection";

	@ConfigItem(
		keyName = "proximityDuradel",
		name = "Duradel",
		description = "Alert when approaching Duradel (or Kuradal) in Shilo Village.",
		section = "proximitySection",
		position = 0
	)
	default boolean proximityDuradel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "proximityNieve",
		name = "Nieve / Steve",
		description = "Alert when approaching Nieve (or Steve) in the Gnome Stronghold.",
		section = "proximitySection",
		position = 1
	)
	default boolean proximityNieve()
	{
		return true;
	}

	@ConfigItem(
		keyName = "proximityKonar",
		name = "Konar quo Maten",
		description = "Alert when approaching Konar on Mount Karuulm.",
		section = "proximitySection",
		position = 2
	)
	default boolean proximityKonar()
	{
		return true;
	}

	@ConfigItem(
		keyName = "proximityKrystilia",
		name = "Krystilia",
		description = "Alert when approaching Krystilia in Edgeville.",
		section = "proximitySection",
		position = 3
	)
	default boolean proximityKrystilia()
	{
		return true;
	}
}
